# Turns the real files in data/raw/ (built by scripts/fetch_corpus.py from
# corpus_manifest.json's public URLs) into Passage records: one per real PDF page for the
# PDF sources, and one per fixed-size word-count chunk for the two Wikipedia wikitext
# sources (which have no page breaks of their own). Writes data/corpus.jsonl. Both
# data/raw/ and data/corpus.jsonl are gitignored and regenerated by
# `python scripts/fetch_corpus.py && python -m assistant.ingest`; this project never
# commits the extracted text of the CXL/PCIe specification PDFs, which are copyrighted by
# the CXL Consortium and PCI-SIG, not public domain.
from __future__ import annotations

import json
import re
from dataclasses import asdict, dataclass
from pathlib import Path

from pypdf import PdfReader

ROOT = Path(__file__).resolve().parents[1]
RAW_DIR = ROOT / "data" / "raw"
CORPUS_PATH = ROOT / "data" / "corpus.jsonl"
MANIFEST_PATH = ROOT / "corpus_manifest.json"

WIKI_PAGE_WORDS = 450  # chunk size standing in for a "page" for sources with no page breaks


@dataclass(frozen=True)
class Passage:
    doc_id: str
    title: str
    page_number: int
    text: str
    source_format: str


def _extract_pdf_pages(path: Path, title: str, doc_id: str) -> list[Passage]:
    reader = PdfReader(str(path))
    passages = []
    for i, page in enumerate(reader.pages, start=1):
        text = (page.extract_text() or "").strip()
        text = re.sub(r"\s+", " ", text)
        if text:
            passages.append(Passage(doc_id=doc_id, title=title, page_number=i, text=text, source_format="pdf"))
    return passages


_WIKI_TEMPLATE = re.compile(r"\{\{[^{}]*\}\}")
_WIKI_TABLE = re.compile(r"\{\|.*?\|\}", re.DOTALL)
_WIKI_REF = re.compile(r"<ref[^>]*>.*?</ref>|<ref[^>]*/>", re.DOTALL)
_WIKI_COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)
_WIKI_LINK = re.compile(r"\[\[(?:[^|\]]*\|)?([^\]]+)\]\]")
_WIKI_EXTLINK = re.compile(r"\[https?://\S+\s+([^\]]+)\]")
_WIKI_BOLDITALIC = re.compile(r"'''?")
_WIKI_HEADING = re.compile(r"^=+\s*(.*?)\s*=+$", re.MULTILINE)
_WIKI_TAG = re.compile(r"<[^>]+>")


def _clean_wikitext(raw: str) -> str:
    text = raw
    for _ in range(3):  # templates can nest a little; a few passes clears most of them
        text = _WIKI_TEMPLATE.sub(" ", text)
    text = _WIKI_TABLE.sub(" ", text)
    text = _WIKI_REF.sub(" ", text)
    text = _WIKI_COMMENT.sub(" ", text)
    text = _WIKI_LINK.sub(r"\1", text)
    text = _WIKI_EXTLINK.sub(r"\1", text)
    text = _WIKI_BOLDITALIC.sub("", text)
    text = _WIKI_HEADING.sub(r"\1.", text)
    text = _WIKI_TAG.sub(" ", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip()


def _extract_wiki_pages(path: Path, title: str, doc_id: str) -> list[Passage]:
    cleaned = _clean_wikitext(path.read_text(encoding="utf-8"))
    words = cleaned.split(" ")
    passages = []
    for i, start in enumerate(range(0, len(words), WIKI_PAGE_WORDS), start=1):
        chunk = " ".join(words[start:start + WIKI_PAGE_WORDS]).strip()
        if chunk:
            passages.append(Passage(doc_id=doc_id, title=title, page_number=i, text=chunk, source_format="wikitext"))
    return passages


def build_corpus(raw_dir: Path = RAW_DIR, manifest_path: Path = MANIFEST_PATH, corpus_path: Path = CORPUS_PATH) -> list[Passage]:
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    passages: list[Passage] = []
    for source in manifest["sources"]:
        ext = ".pdf" if source["format"] == "pdf" else ".wikitext"
        path = raw_dir / f"{source['id']}{ext}"
        if not path.exists():
            raise FileNotFoundError(f"{path} missing; run scripts/fetch_corpus.py first")
        if source["format"] == "pdf":
            passages.extend(_extract_pdf_pages(path, source["title"], source["id"]))
        else:
            passages.extend(_extract_wiki_pages(path, source["title"], source["id"]))

    corpus_path.parent.mkdir(parents=True, exist_ok=True)
    with open(corpus_path, "w", encoding="utf-8") as f:
        for p in passages:
            f.write(json.dumps(asdict(p)) + "\n")
    return passages


def load_corpus(corpus_path: Path = CORPUS_PATH) -> list[Passage]:
    if not corpus_path.exists():
        raise FileNotFoundError(f"{corpus_path} missing; run `python -m assistant.ingest` first")
    passages = []
    with open(corpus_path, encoding="utf-8") as f:
        for line in f:
            passages.append(Passage(**json.loads(line)))
    return passages


if __name__ == "__main__":
    built = build_corpus()
    by_doc: dict[str, int] = {}
    for p in built:
        by_doc[p.doc_id] = by_doc.get(p.doc_id, 0) + 1
    print(json.dumps({"total_passages": len(built), "by_doc": by_doc}, indent=2))
